"""Regression tests for the behavior specified in SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    events = [event("a", 1, True), event("b", 1, None), event("c", 1, False)]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([event("b", 1, None)]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 1, False), event("c", 1, None), event("d", 1, False)],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_empty(groups):
    rate = pooled_flag_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flag_values_and_whitespace():
    assert parse_transcript_log([" a , 3 , 1 \n", " b , -2 , 0 ", " c , 4 , \t"]) == [
        event("a", 3, True), event("b", -2, False), event("c", 4, None),
    ]


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", " \t# a,b,c,d", "a,1,1", "\n", "b,2,0"]
    assert parse_transcript_log(iter(lines)) == [event("a", 1, True), event("b", 2, False)]
    assert parse_transcript_log(["", " # comment"]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["# comment", " \t", "valid,2,1", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    first = event("b", 10, True)
    last = event("b", 2, None)
    events = [first, event("z", 1, True), event("a", 2, False), last]
    assert dedupe_transcripts(events) == [events[1], events[2], last]
    assert events == [first, event("z", 1, True), event("a", 2, False), last]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_zero_filled_range():
    events = [
        event("before", 0, True), event("a", 1, True), event("b", 1, True),
        event("c", 2, False), event("d", 2, None), event("e", 4, True),
        event("after", 5, True),
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_monitor_summary_pooled_rounded_rate_and_calendar_window():
    groups = {
        "a": [event("a", 1, True)],
        "b": [event("b", 3, True), event("c", 5, None)],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary(groups, 100)["recent"] == 2
    assert monitor_summary(groups, 0)["recent"] == 0


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [event("z", 1, True)],
        "empty": [],
        "b": [event("b", 1, True), event("c", 1, None)],
        "a": [event("a", 1, True)],
        "zero": [event("d", 1, False)],
    }
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 1) == []
    assert top_flagged_groups({}, 1) == []


def test_flag_rate_by_group_sorted_with_none_for_empty():
    groups = {
        "z": [event("z", 1, True), event("x", 1, None)],
        "b": [],
        "a": [event("a", 1, False)],
    }
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 0.0, "b": None, "z": 0.5}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([1, 2, 0, 3], 2),
     ([1, -1, 2, 3, 4], 3), ([1, 0, 2, 0, 3], 1), ([1, 2, 3], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
